steps.script:
mkdir /tmp/amy-zig && cd /tmp/amy-zig && printf 'export fn answer() c_int { return 42; }
' > answer.zig && printf 'int answer(void); int main(void) { return answer(); }
' > main.c && zig build-obj -ofmt=c -femit-bin=answer.c answer.zig && cc -I /usr/lib/zig main.c answer.c -o answer && man zig > /dev/null && ./answer; test $? = 42 && printf 'const std = @import("std");
pub fn main() void { std.debug.print("{d}", .{6 * 7}); }
' > hello.zig && zig build-exe -target wasm64-emscripten -fsingle-threaded -ofmt=c -lc -femit-bin=hello.c hello.zig && cc -Wno-incompatible-pointer-types '-Dzig_unimplemented()=(__builtin_trap(),0)' -I /usr/lib/zig hello.c -o hello && test "$(./hello 2>&1)" = 42
